import { writeFileSync, copyFileSync, unlinkSync, existsSync, statSync, readdirSync } from 'fs';
import { resolve, dirname, basename, extname } from 'path';
import { fileURLToPath } from 'url';

// ESM compatibility - __dirname is not available in ESM
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

/**
 * Utilities for creating and managing test files.
 * Files are created in tests/web-e2e/fixtures/files/ and tracked for cleanup.
 *
 * Static fixtures (test-image.png, test-document.pdf, test-file.txt)
 * are committed to the repo. Generated files use unique names and are
 * cleaned up after each test run.
 */

const FIXTURES_DIR = resolve(__dirname, '../fixtures/files');
const createdFiles: string[] = [];

/** Names of committed fixture files — never overwrite or delete these. */
const COMMITTED_FIXTURES = new Set(
  readdirSync(FIXTURES_DIR).filter((f) => !f.startsWith('.')),
);

interface TestTextFile {
  name: string;
  content: string;
  path: string;
}

interface TestBinaryFile {
  name: string;
  path: string;
  sizeKb: number;
}

